1083	// Attaches compensation results to a failed run. Successful outputs and the
1084	// original terminal status stay untouched; compensation records live on
1085	// their own fields, never in the regular node trace.
1086	async function withCompensation(result, state, operations) {
1087	  const outcome = await compensateRun(state, operations);
1088	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1089	  result.compensationAttempts = outcome.attempts;
