1106	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1107	  const signal = resolveRunSignal(options);
1108	  const nodes = validateWorkflow(workflow);
1109	  verifyOperations(nodes, operations);
1110	
1111	  const state = createRunState(nodes, workflow, input);
1112	
1113	  // A signal that is already aborted stops the run before the first node —
1114	  // but only after the definition and the operation registrations above have
1115	  // been checked. Nothing executes and nothing is compensated.
1116	  if (signal && signal.aborted) {
1117	    return withCompensation(cancelledResult(state), state, operations);
1118	  }
